/*
 * ══════════════════════════════════════════════════════════════════════════
 * THE PRODUCTION GRAPH — one page for the Production phase.
 *
 * Built to design_handoff_production_graph/FE-*. Every node is a view of rows
 * that already exist (a shot and its frames, a sequence, a music cue, the assets
 * a generation made), read in one call from GET /projects/:id/production-graph.
 * Every paid action goes through the functions the old pages already use —
 * regenerateStoryboard, refineFrame, generateSequence, confirmPaidImage — so the
 * graph cannot describe a generation differently from the board.
 *
 * Behind the `production_graph` setting. Off, the phase is its eight pages.
 * ══════════════════════════════════════════════════════════════════════════
 */
let PRODUCTION_GRAPH_ON = false;
const PG_OLD_PAGES = ['shotboard', 'videoshots', 'music', 'musiccues', 'playback', 'pipeline', 'flows'];
const PG = {
    graph: null, byKey: new Map(), sel: null, zoom: 0.9, pan: { x: 0, y: 0 }, scene: 'all',
    busy: new Map(), drawerCache: {}, play: { index: 0, playing: false, t0: 0, timer: null, stills: true, audio: true },
    fitted: false, menuFor: null,
    running: new Map(), pollTimer: null, behindOnly: false, queue: null, queueOpen: false,
    picked: new Set(), add: null, selBeforeClick: null,
};

/**
 * Which set of pages the menu shows. The eight old pages stay in the build and
 * reachable by URL either way; the Score workspace stays in the menu too,
 * because the graph opens it rather than replacing it.
 */
async function applyProductionFlag() {
    pgEnsureSide();
    try {
        const r = await api('/settings');
        PRODUCTION_GRAPH_ON = !!(r && r.settings && r.settings.production_graph);
    } catch (_) { /* a settings read that fails leaves the classic pages, which is the safe side */ }
    document.querySelectorAll('.nav-item[data-page]').forEach(b => {
        const p = b.dataset.page;
        const hide = (p === 'productiongraph' && !PRODUCTION_GRAPH_ON) || (PRODUCTION_GRAPH_ON && PG_OLD_PAGES.includes(p));
        if (hide) b.dataset.flagHidden = '1'; else delete b.dataset.flagHidden;
    });
    const toggle = document.getElementById('settingsProductionGraph');
    if (toggle) toggle.checked = PRODUCTION_GRAPH_ON;
    pgRenderSide();
    if (window.feShowPhase) window.feShowPhase();
}

async function saveProductionGraphFlag() {
    const box = document.getElementById('settingsProductionGraph');
    if (!box) return;
    try {
        await api('/settings', { method: 'PUT', body: JSON.stringify({ production_graph: box.checked }) });
        setStatus(box.checked ? 'Production is now one graph.' : 'Production is back to its separate pages.');
        await applyProductionFlag();
    } catch (err) {
        box.checked = !box.checked;
        setStatus('Could not save: ' + err.message);
    }
}

// ── In-betweens between two key shots ────────────────────────────────────
/*
 * Connect 1A to 1B (drag 1A's image port onto 1B, or "In-betweens to the next
 * shot" on 1A), say how many frames and how often, and direct them: each frame
 * on its own, and stretches of time on their lanes. Everything that spends goes
 * through the one confirmation, reading the route's own free plan first.
 */
const IB = { setup: null, span: null, sel: 0, rangeEdit: null, price: null };

// ── Side panel: outline + palette ─────────────────────────────────────────

function pgRenderSide() {
    const host = document.getElementById('pgSidePanel');
    if (!host) return;
    const on = PRODUCTION_GRAPH_ON && state.currentProject;
    host.style.display = on ? '' : 'none';
    host.dataset.flagHidden = on ? '' : '1';
    if (!on) return;
    // The outline needs the graph even before the page is opened.
    if (!PG.graph || PG.graph.project_id !== state.currentProject.id) {
        if (!PG.loadingSide) { PG.loadingSide = true; loadProductionGraph().finally(() => { PG.loadingSide = false; }); }
        return;
    }
    const find = (PG.find || '').toLowerCase();
    const scenes = [];
    for (const s of pgShots()) {
        if (find && !String(s.shot_code).toLowerCase().includes(find)) continue;
        let sc = scenes.find(x => x.id === s.scene_id);
        if (!sc) scenes.push(sc = { id: s.scene_id, label: s.scene_label, shots: [] });
        sc.shots.push(s);
    }
    const onGraph = s => pgVisible(s);
    const list = document.getElementById('pgOutline');
    if (list) list.innerHTML = scenes.map(sc => `<div class="pg-side-scene"><span>${esc(sc.label)}</span><span>${sc.shots.length}</span></div>`
        + sc.shots.map(s => {
            const seq = s.sequence_id ? pgNode('seq:' + s.sequence_id) : null;
            const card = pgCollapsedOf(s.key);
            const note = card ? `in ${card.label} (collapsed)` : !onGraph(s) ? 'off graph' : seq ? seq.name : '';
            return `<div class="pg-side-row${PG.sel === s.key ? ' on' : ''}" draggable="true"
                ondragstart="event.dataTransfer.setData('text/pg-add','${s.key}')" onclick="pgSideClick('${s.key}')">
                <i style="background:${s.frames.length ? '#4fd39c' : '#f08a8a'}"></i><span>${esc(s.shot_code)}</span><span class="note">${esc(note)}</span></div>`;
        }).join('')).join('') || '<div class="pg-note">No shots yet.</div>';
}

// After every DOMContentLoaded listener, so the chrome has built the panel the
// outline and palette go into.
document.addEventListener('DOMContentLoaded', () => setTimeout(applyProductionFlag, 0));

